INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B1', '刮', 'guā', 'cạo, thổi (gió)', 'V', '冬天東北季風來的時候，陽明山上總是刮著強風。', 'dōng tiān dōng běi jì fēng lái de shí hòu ， yáng míng shān shàng zǒng shì guā zhù qiáng fēng 。', 'Khi gió mùa đông bắc đến vào mùa đông, trên núi Dương Minh Sơn luôn có gió mạnh thổi.', 'monchinese', 589) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
