INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B1', '顧客', 'gùkè', 'khách hàng', 'N', '這家永和豆漿的顧客每天早上都很多。', 'zhè jiā yǒng hé dòu jiāng de gù kè měi tiān zǎo shàng dōu hěn duō 。', 'Quán sữa đậu nành Vĩnh Hòa này mỗi sáng đều có rất nhiều khách hàng.', 'monchinese', 864) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
