INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B1', '實力', 'shílì', 'thực lực', 'N', '台灣的半導體產業在世界上很有實力。', 'tái wān de bàn dǎo tǐ chǎn yè zài shì jiè shàng hěn yǒu shí lì 。', 'Ngành công nghiệp bán dẫn của Đài Loan có sức mạnh lớn trên thế giới.', 'monchinese', 1020) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
