INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '備', 'bèi', 'chuẩn bị', 'V', '在外出前，我們應該備好雨具，尤其是在梅雨季。', 'zài wài chū qián ， wǒ men yīng gāi bèi hǎo yǔ jù ， yóu qí shì zài méi yǔ jì 。', 'Trước khi ra ngoài, chúng ta nên chuẩn bị đồ đi mưa, đặc biệt là vào mùa mưa dầm.', 'monchinese', 227) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
