INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '高大', 'gāodà', 'cao lớn, to lớn', 'Vs', '他的父親很高大，走在人群中很顯眼。', 'tā de fù qīn hěn gāo dà ， zǒu zài rén qún zhōng hěn xiǎn yǎn 。', 'Bố anh ấy rất cao lớn, đứng trong đám đông rất nổi bật.', 'monchinese', 374) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
