INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '世紀', 'shìjì', 'thế kỷ', 'N', '在17世紀，荷蘭人曾來到臺灣進行貿易和殖民。', 'zài 1 7 shì jì ， hé lán rén céng lái dào tái wān jìn xíng mào yì hé zhí mín 。', 'Vào thế kỷ 17, người Hà Lan từng đến Đài Loan để giao thương và thực dân hóa.', 'monchinese', 412) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
