INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '濃厚', 'nónghòu', 'đậm đà, nồng hậu', 'Vs', '這湯的湯頭很濃厚。', 'zhè tāng de tāng tóu hěn nóng hòu 。', 'Nước dùng của món canh này rất đậm đà.', 'monchinese', 724) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '熱愛', 'rè&#x27;ài', 'nhiệt tình yêu thương, yêu tha thiết', 'Vst', '我熱愛我的工作。', 'wǒ rè ài wǒ de gōng zuò 。', 'Tôi nhiệt tình yêu thương công việc của mình.', 'monchinese', 725) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '熱烈', 'rèliè', 'nhiệt liệt', 'Vs', '現場響起了熱烈的掌聲。', 'xiàn chǎng xiǎng qǐ le rè liè de zhǎng shēng 。', 'Tại hiện trường vang lên tràng pháo tay nhiệt liệt.', 'monchinese', 726) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '慎重', 'shènzhòng', 'thận trọng', 'Vs', '買房是大事，一定要慎重評估地點和價格。', 'mǎi fáng shì dà shì ， yí dìng yào shèn zhòng píng gū dì diǎn hé jià gé 。', 'Mua nhà là chuyện lớn, nhất định phải thận trọng đánh giá địa điểm và giá cả.', 'monchinese', 727) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '事件', 'shìjiàn', 'sự kiện', 'N', '這次在臺北小巨蛋舉辦的演唱會是一個備受矚目的音樂事件。', 'zhè cì zài tái běi xiǎo jù dàn jǔ bàn de yǎn chàng huì shì yí gè bèi shòu zhǔ mù dì yīn lè shì jiàn 。', 'Buổi hòa nhạc lần này được tổ chức tại Nhà thi đấu Đài Bắc là một sự kiện âm nhạc được mong chờ.', 'monchinese', 728) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '市民', 'shìmín', 'thị dân, người dân thành phố', 'N', '臺北市民可以透過「1999市民服務專線」反映市政問題。', 'tái běi shì mín kě yǐ tòu guò 「 1 9 9 9 shì mín fú wù zhuān xiàn 」 fǎn yìng shì zhèng wèn tí 。', 'Công dân Đài Bắc có thể phản ánh các vấn đề đô thị thông qua "Đường dây nóng dịch vụ công dân 1999".', 'monchinese', 729) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '通信', 'tōngxìn', 'thông tin, liên lạc (qua thư)', 'V-sep', '我和朋友用電子郵件通信。', 'wǒ hé péng yǒu yòng diàn zǐ yóu jiàn tōng xìn 。', 'Tôi và bạn bè giao tiếp qua email.', 'monchinese', 730) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '通訊', 'tōngxùn', 'truyền thông, thông tin liên lạc', 'N', '現代通訊很方便。', 'xiàn dài tōng xùn hěn fāng biàn 。', 'Giao tiếp hiện đại rất tiện lợi.', 'monchinese', 731) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '無意', 'wúyì', 'vô ý, không cố ý', 'Vs', '他無意中發現了一個秘密。', 'tā wú yì zhōng fā xiàn le yí gè mì mì 。', 'Anh ấy vô tình phát hiện ra một bí mật.', 'monchinese', 732) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
