INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '意外', 'yìwài', 'bất ngờ, ngoài ý muốn', 'Vs', '這次旅遊我們遇到了一點意外。', 'zhè cì lǚ yóu wǒ men yù dào le yì diǎn yì wài 。', 'Chuyến du lịch lần này chúng tôi gặp một chút bất ngờ.', 'monchinese', 735) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
