INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '證件', 'zhèngjiàn', 'giấy tờ tùy thân', 'N', '出國旅行需要準備很多證件。', 'chū guó lǚ xíng xū yào zhǔn bèi hěn duō zhèng jiàn 。', 'Đi du lịch nước ngoài cần chuẩn bị nhiều giấy tờ tùy thân.', 'monchinese', 737) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '證據', 'zhèngjù', 'bằng chứng, chứng cứ', 'N', '警方正在尋找犯罪證據。', 'jǐng fāng zhèng zài xún zhǎo fàn zuì zhèng jù 。', 'Cảnh sát đang tìm kiếm bằng chứng phạm tội.', 'monchinese', 738) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
