INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '深刻', 'shēnkè', 'sâu sắc', 'Vs', '臺灣的熱情和美食給我留下了深刻的印象。', 'tái wān de rè qíng hé měi shí gěi wǒ liú xià le shēn kè de yìn xiàng 。', 'Lòng hiếu khách và ẩm thực ngon của Đài Loan đã để lại ấn tượng sâu sắc trong tôi.', 'monchinese', 1021) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
