INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '美食', 'měishí', 'món ngon, mỹ thực', 'N', '臺灣有很多好吃的美食。', 'tái wān yǒu hěn duō hǎo chī de měi shí 。', 'Đài Loan có rất nhiều món ăn ngon.', 'monchinese', 1105) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '足夠', 'zúgòu', 'đầy đủ', 'Vs', '我們的食物足夠大家吃。', 'wǒ men de shí wù zú gòu dà jiā chī 。', 'Thức ăn của chúng tôi đủ cho mọi người ăn.', 'monchinese', 1106) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '鼓', 'gǔ', 'cái trống', 'N', '台灣廟會裡常會聽到熱鬧的鼓聲。', 'tái wān miào huì lǐ cháng huì tīng dào rè nào de gǔ shēng 。', 'Trong các lễ hội đền chùa ở Đài Loan, người ta thường nghe thấy tiếng trống rộn ràng.', 'monchinese', 1107) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '跪', 'guì', 'quỳ', 'Vi', '小狗跪在地上。', 'xiǎo gǒu guì zài dì shàng 。', 'Chú chó con quỳ trên mặt đất.', 'monchinese', 1108) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '願', 'yuàn', 'nguyện, mong muốn', 'Vst', '我願幫你。', 'wǒ yuàn bāng nǐ 。', 'Tôi nguyện giúp bạn.', 'monchinese', 1109) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '罪', 'zuì', 'tội, tội lỗi', 'N', '偷竊是一種罪。', 'tōu qiè shì yì zhǒng zuì 。', 'Trộm cắp là một tội lỗi.', 'monchinese', 1110) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '廣大', 'guǎngdà', 'rộng lớn, đông đảo', 'Vs', '台灣擁有廣大的海洋資源，適合發展漁業。', 'tái wān yōng yǒu guǎng dà de hǎi yáng zī yuán ， shì hé fā zhǎn yú yè 。', 'Đài Loan có nguồn tài nguyên biển rộng lớn, thích hợp để phát triển ngành thủy sản.', 'monchinese', 1111) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光亮', 'guāngliàng', 'sáng sủa, sáng bóng', 'Vs', '剛擦過的地板看起來很光亮。', 'gāng cā guò de dì bǎn kàn qǐ lái hěn guāng liàng 。', 'Sàn nhà vừa lau trông rất sáng bóng.', 'monchinese', 1112) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光臨', 'guānglín', 'ghé thăm, quang lâm (lịch sự)', 'V', '歡迎光臨我們的珍珠奶茶店！', 'huān yíng guāng lín wǒ men de zhēn zhū nǎi chá diàn ！', 'Hoan nghênh quý khách ghé thăm cửa hàng trà sữa trân châu của chúng tôi!', 'monchinese', 1113) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光明', 'guāngmíng', 'quang minh, tươi sáng', 'Vs', '願我們的未來充滿光明。', 'yuàn wǒ men de wèi lái chōng mǎn guāng míng 。', 'Chúc tương lai của chúng ta tràn đầy ánh sáng.', 'monchinese', 1114) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光榮', 'guāngróng', 'vinh quang, vẻ vang', 'Vs', '代表台灣參加國際比賽是一件光榮的事。', 'dài biǎo tái wān cān jiā guó jì bǐ sài shì yí jiàn guāng róng de shì 。', 'Đại diện Đài Loan tham gia cuộc thi quốc tế là một điều vinh quang.', 'monchinese', 1115) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光是', 'guāngshì', 'chỉ riêng, chỉ là', 'Adv', '光是聽他唱歌就覺得很享受。', 'guāng shì tīng tā chàng gē jiù jué dé hěn xiǎng shòu 。', 'Chỉ riêng việc nghe anh ấy hát đã thấy rất thích rồi.', 'monchinese', 1116) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '觀光', 'guānguāng', 'tham quan, du lịch', 'Vi / N', '假日很多人會去九份老街觀光。', 'jiǎ rì hěn duō rén huì qù jiǔ fèn lǎo jiē guān guāng 。', 'Ngày nghỉ rất nhiều người đi tham quan phố cổ Cửu Phần.', 'monchinese', 1117) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '光線', 'guāngxiàn', 'ánh sáng, tia sáng', 'N', '這間咖啡廳的光線很柔和，很適合閱讀。', 'zhè jiàn kā fēi tīng de guāng xiàn hěn róu hé ， hěn shì hé yuè dú 。', 'Ánh sáng trong quán cà phê này rất dịu nhẹ, rất thích hợp để đọc sách.', 'monchinese', 1118) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '關鍵', 'guānjiàn', 'then chốt, mấu chốt', 'N', '團隊合作是這次專案成功的關鍵。', 'tuán duì hé zuò shì zhè cì zhuān àn chéng gōng de guān jiàn 。', 'Làm việc nhóm là yếu tố then chốt cho sự thành công của dự án này.', 'monchinese', 1119) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '冠軍', 'guànjūn', 'quán quân, vô địch', 'N', '台灣棒球隊去年奪得了亞洲冠軍。', 'tái wān bàng qiú duì qù nián duó dé le yā zhōu guān jūn 。', 'Đội bóng chày Đài Loan năm ngoái đã giành chức vô địch châu Á.', 'monchinese', 1120) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '慣例', 'guànlì', 'thông lệ, quy ước', 'N', '台灣的許多家庭慣例是除夕夜要吃團圓飯。', 'tái wān de xū duō jiā tíng guàn lì shì chú xī yè yào chī tuán yuán fàn 。', 'Nhiều gia đình Đài Loan có thông lệ là đêm Giao thừa phải ăn bữa cơm đoàn viên.', 'monchinese', 1121) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '關上', 'guānshàng', 'đóng lại', 'V', '出門前記得把燈關上。', 'chū mén qián jì dé bǎ dēng guān shàng 。', 'Trước khi ra ngoài nhớ tắt đèn.', 'monchinese', 1122) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '官員', 'guānyuán', 'quan chức, viên chức', 'N', '新北市政府的官員今天來學校參觀。', 'xīn běi shì zhèng fǔ de guān yuán jīn tiān lái xué xiào cān guān 。', 'Các quan chức của chính quyền thành phố Tân Bắc hôm nay đến thăm trường học.', 'monchinese', 1123) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '管制', 'guǎnzhì', 'quản chế, kiểm soát', 'V', '颱風天，政府通常會實施山區道路管制。', 'tái fēng tiān ， zhèng fǔ tōng cháng huì shí shī shān qū dào lù guǎn zhì 。', 'Ngày bão, chính phủ thường thực hiện kiểm soát đường bộ ở khu vực miền núi.', 'monchinese', 1124) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '瓜子', 'guāzǐ', 'hạt dưa', 'N', '農曆新年時，台灣家庭常會準備瓜子和糖果招待客人。', 'nóng lì xīn nián shí ， tái wān jiā tíng cháng huì zhǔn bèi guā zǐ hé táng guǒ zhāo dài kè rén 。', 'Vào dịp Tết Nguyên Đán, các gia đình Đài Loan thường chuẩn bị hạt dưa và kẹo để đãi khách.', 'monchinese', 1125) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '海關', 'hǎiguān', 'hải quan', 'N', '我通過了海關檢查。', 'wǒ tōng guò le hǎi guān jiǎn chá 。', 'Tôi đã qua kiểm tra hải quan.', 'monchinese', 1126) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '儘管', 'jǐnguǎn', 'cứ, cứ việc', 'Adv', '儘管下雨，我們還是去散步了。', 'jǐn guǎn xià yǔ ， wǒ men hái shì qù sàn bù le 。', 'Mặc dù trời mưa, chúng tôi vẫn đi dạo.', 'monchinese', 1127) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '客觀', 'kèguān', 'khách quan', 'Vs', '我們討論這個問題時要保持客觀。', 'wǒ men tǎo lùn zhè gè wèn tí shí yào bǎo chí kè guān 。', 'Chúng ta cần phải khách quan khi thảo luận vấn đề này.', 'monchinese', 1128) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '口語', 'kǒuyǔ', 'khẩu ngữ, ngôn ngữ nói', 'N', '這個詞彙在口語中很常用。', 'zhè gè cí huì zài kǒu yǔ zhōng hěn cháng yòng 。', 'Từ vựng này rất phổ biến trong khẩu ngữ.', 'monchinese', 1129) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '美觀', 'měiguān', 'đẹp mắt, mỹ quan', 'Vs', '這棟建築設計得很美觀。', 'zhè dòng jiàn zhù shè jì dé hěn měi guān 。', 'Tòa nhà này được thiết kế rất đẹp mắt.', 'monchinese', 1130) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '推廣', 'tuīguǎng', 'phổ biến, quảng bá', 'V', '他們推廣環保理念。', 'tā men tuī guǎng huán bǎo lǐ niàn 。', 'Họ quảng bá ý tưởng bảo vệ môi trường.', 'monchinese', 1131) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '外觀', 'wàiguān', 'bề ngoài, ngoại quan', 'N', '這輛車的外觀很新潮。', 'zhè liàng chē de wài guān hěn xīn cháo 。', 'Ngoại quan của chiếc xe này rất thời thượng.', 'monchinese', 1132) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '維護', 'wéihù', 'duy trì, bảo vệ', 'V', '我們要維護環境。', 'wǒ men yào wéi hù huán jìng 。', 'Chúng ta phải bảo vệ môi trường.', 'monchinese', 1133) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '血管', 'xuèguǎn', 'mạch máu, huyết quản', 'N', '醫生的手很巧，一下子就找到我的血管抽血。', 'yī shēng de shǒu hěn qiǎo ， yí xià zǐ jiù zhǎo dào wǒ de xuè guǎn chōu xuè 。', 'Bàn tay của bác sĩ rất khéo léo, một lát là tìm được mạch máu của tôi để lấy máu.', 'monchinese', 1134) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '星光', 'xīngguāng', 'ánh sao', 'N', '抬頭望著夜空，可以看到點點星光。', 'tái tóu wàng zhù yè kōng ， kě yǐ kàn dào diǎn diǎn xīng guāng 。', 'Ngước nhìn bầu trời đêm, có thể thấy những đốm sáng sao.', 'monchinese', 1135) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '有關', 'yǒuguān', 'có liên quan, về', 'Prep / Vs', '這和我有關。', 'zhè hé wǒ yǒu guān 。', 'Chuyện này có liên quan đến tôi.', 'monchinese', 1136) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '月光', 'yuèguāng', 'ánh trăng', 'N', '今晚的月光很美。', 'jīn wǎn de yuè guāng hěn měi 。', 'Ánh trăng tối nay rất đẹp.', 'monchinese', 1137) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '主觀', 'zhǔguān', 'chủ quan', 'Vs', '這件事很主觀，每個人的看法都不一樣。', 'zhè jiàn shì hěn zhǔ guān ， měi gè rén de kàn fǎ dōu bù yí yàng 。', 'Chuyện này rất chủ quan, ý kiến mỗi người đều khác nhau.', 'monchinese', 1138) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '怪不得', 'guàibude', 'thảo nào, hèn chi', 'Adv', '怪不得他那麼累，原來是前一晚熬夜看棒球賽。', 'guài bù dé tā nà me lèi ， yuán lái shì qián yì wǎn áo yè kàn bàng qiú sài 。', 'Thảo nào anh ấy mệt mỏi thế, hóa ra là đêm hôm trước thức khuya xem trận bóng chày.', 'monchinese', 1139) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '規畫', 'guīhuà', 'quy hoạch, kế hoạch', 'N / V', '我們規畫了週末去墾丁的行程。', 'wǒ men guī huà le zhōu mò qù kěn dīng de xíng chéng 。', 'Chúng tôi đã lên kế hoạch cho chuyến đi đến Kenting vào cuối tuần.', 'monchinese', 1140) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
