INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '少年', 'shàonián', 'thiếu niên', 'N', '臺灣許多少年放學後喜歡在社區的籃球場打球。', 'tái wān xū duō shào nián fàng xué hòu xǐ huān zài shè qū de lán qiú chǎng dǎ qiú 。', 'Nhiều thiếu niên Đài Loan thích chơi bóng rổ ở sân bóng rổ cộng đồng sau giờ học.', 'monchinese', 1216) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '少女', 'shàonǚ', 'thiếu nữ', 'N', '許多臺灣少女喜歡穿漂亮的洋裝。', 'xū duō tái wān shào nǚ xǐ huān chuān piào liang de yáng zhuāng 。', 'Nhiều thiếu nữ Đài Loan thích mặc những chiếc váy đẹp.', 'monchinese', 1217) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '少數', 'shǎoshù', 'thiểu số, số ít', 'Det', '在臺灣，會說原住民語的年輕人是少數。', 'zài tái wān ， huì shuō yuán zhù mín yǔ de nián qīng rén shì shǎo shù 。', 'Ở Đài Loan, những người trẻ biết nói tiếng thổ dân là thiểu số.', 'monchinese', 1218) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '稍微', 'shāowēi', 'hơi, một chút', 'Adv', '這杯珍珠奶茶可以稍微少冰嗎？', 'zhè bēi zhēn zhū nǎi chá kě yǐ shāo wēi shǎo bīng má ？', 'Ly trà sữa trân châu này có thể bớt đá một chút được không?', 'monchinese', 1219) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '信號', 'xìnhào', 'tín hiệu', 'N', '紅燈是停止的信號。', 'hóng dēng shì tíng zhǐ de xìn hào 。', 'Đèn đỏ là tín hiệu dừng lại.', 'monchinese', 1220) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '要好', 'yàohǎo', 'thân thiết, có quan hệ tốt', 'Vs', '他們兩個人很要好。', 'tā men liǎng gè rén hěn yào hǎo 。', 'Hai người họ rất thân thiết.', 'monchinese', 1221) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '友好', 'yǒuhǎo', 'thân thiện, hữu hảo', 'Vs', '他們是友好鄰居。', 'tā men shì yǒu hǎo lín jū 。', 'Họ là hàng xóm thân thiện.', 'monchinese', 1222) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
