INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '最少', 'zuìshǎo', 'ít nhất, tối thiểu', 'Adv', '你最少要讀三本書。', 'nǐ zuì shǎo yào dú sān běn shū 。', 'Bạn cần đọc ít nhất ba cuốn sách.', 'monchinese', 1226) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '打招呼', 'dǎzhāohū', 'chào hỏi', 'V-sep', '遇到鄰居要打招呼。', 'yù dào lín jū yào dǎ zhāo hū 。', 'Gặp hàng xóm phải chào hỏi.', 'monchinese', 1227) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '掛號信', 'guàhàoxìn', 'thư bảo đảm, thư ghi số', 'N', '這份重要文件要用掛號信寄出。', 'zhè fèn zhòng yào wén jiàn yào yòng guà hào xìn jì chū 。', 'Tài liệu quan trọng này cần được gửi bằng thư bảo đảm.', 'monchinese', 1228) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '合', 'hé', 'hợp, vừa', 'Vi / Vs', '我們一起合作完成這個專案。', 'wǒ men yì qǐ hé zuò wán chéng zhè gè zhuān àn 。', 'Chúng tôi cùng nhau hợp tác hoàn thành dự án này.', 'monchinese', 1229) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '射', 'shè', 'bắn, phóng', 'V', '太陽從合歡山的山頂射出第一道曙光。', 'tài yáng cóng hé huān shān de shān dǐng shè chū dì yī dào shǔ guāng 。', 'Mặt trời phát ra tia nắng đầu tiên từ đỉnh núi Hợp Hoan.', 'monchinese', 1230) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
