INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '競爭', 'jìngzhēng', 'cạnh tranh', 'Vi', '學生們在運動會上互相競爭。', 'xué shēng men zài yùn dòng huì shàng hù xiāng jìng zhēng 。', 'Học sinh thi đấu với nhau trong đại hội thể thao.', 'monchinese', 1237) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '糾正', 'jiūzhèng', 'sửa chữa, uốn nắn', 'V', '老師糾正了我的發音錯誤。', 'lǎo shī jiū zhèng le wǒ de fā yīn cuò wù 。', 'Cô giáo đã sửa lỗi phát âm của tôi.', 'monchinese', 1238) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '平衡', 'pínghéng', 'cân bằng, thăng bằng', 'Vst', '他騎腳踏車騎得很平衡。', 'tā qí jiǎo tà chē qí dé hěn píng héng 。', 'Anh ấy đạp xe rất thăng bằng.', 'monchinese', 1239) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '人生', 'rénshēng', 'nhân sinh, cuộc đời', 'N', '人生苦短，要及時行樂。', 'rén shēng kǔ duǎn ， yào jí shí xíng lè 。', 'Cuộc đời ngắn ngủi, phải kịp thời vui chơi.', 'monchinese', 1240) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '生詞', 'shēngcí', 'từ mới', 'N', '學習華語時，我會把遇到的生詞寫在筆記本上。', 'xué xí huá yǔ shí ， wǒ huì bǎ yù dào de shēng cí xiě zài bǐ jì běn shàng 。', 'Khi học tiếng Hoa, tôi sẽ ghi lại những từ mới gặp phải vào sổ tay.', 'monchinese', 1241) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '省得', 'shěngde', 'đỡ phải, để khỏi', 'Vaux', '假日去夜市最好搭捷運，省得找停車位。', 'jiǎ rì qù yè shì zuì hǎo dā jié yùn ， shěng de zhǎo tíng chē wèi 。', 'Cuối tuần đi chợ đêm tốt nhất nên đi MRT, để khỏi phải tìm chỗ đậu xe.', 'monchinese', 1242) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '升級', 'shēngjí', 'thăng cấp, nâng cấp', 'Vp', '臺灣的許多公共建設，如捷運系統，會定期進行維護和升級。', 'tái wān de xū duō gōng gòng jiàn shè ， rú jié yùn xì tǒng ， huì dìng qī jìn xíng wéi hù hé shēng jí 。', 'Nhiều công trình công cộng của Đài Loan, như hệ thống MRT, được bảo trì và nâng cấp định kỳ.', 'monchinese', 1243) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '勝利', 'shènglì', 'thắng lợi', 'Vp', '臺灣的運動員在國際賽事中爭取勝利，為國爭光。', 'tái wān de yùn dòng yuán zài guó jì sài shì zhōng zhēng qǔ shèng lì ， wéi guó zhēng guāng 。', 'Các vận động viên Đài Loan tranh giành chiến thắng trong các giải đấu quốc tế, mang lại vinh quang cho đất nước.', 'monchinese', 1244) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神聖', 'shénshèng', 'thần thánh, thiêng liêng', 'Vs', '這座龍山寺對當地居民來說是個很神聖的信仰中心。', 'zhè zuò lóng shān sì duì dāng dì jū mín lái shuō shì gè hěn shén shèng de xìn yǎng zhōng xīn 。', 'Chùa Long Sơn này là một trung tâm tín ngưỡng rất thiêng liêng đối với cư dân địa phương.', 'monchinese', 1245) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
