INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神氣', 'shénqì', 'oai phong, đắc ý', 'Vs', '小朋友穿著新衣服，走起路來特別神氣。', 'xiǎo péng yǒu chuān zhù xīn yī fu ， zǒu qǐ lù lái tè bié shén qì 。', 'Em bé mặc quần áo mới, đi bộ trông rất oai phong/đắc ý.', 'monchinese', 1272) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '始終', 'shǐzhōng', 'từ đầu đến cuối, luôn luôn', 'Adv', '他始終相信自己會成功。', 'tā shǐ zhōng xiāng xìn zì jǐ huì chéng gōng 。', 'Anh ấy luôn tin rằng mình sẽ thành công.', 'monchinese', 1273) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '中毒', 'zhòngdú', 'trúng độc, ngộ độc', 'Vp-sep', '他吃了壞掉的食物，結果中毒了。', 'tā chī le huài diào de shí wù ， jié guǒ zhòng dú le 。', 'Anh ấy ăn phải thức ăn ôi thiu nên bị ngộ độc.', 'monchinese', 1274) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
