INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '零售', 'língshòu', 'bán lẻ', 'V', '這家店不零售，只批發。', 'zhè jiā diàn bù líng shòu ， zhī pī fā 。', 'Cửa hàng này không bán lẻ, chỉ bán sỉ.', 'monchinese', 1302) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '落後', 'luòhòu', 'tụt hậu, lạc hậu', 'Vpt', '我們班的成績在數學方面有點落後。', 'wǒ men bān de chéng jì zài shù xué fāng miàn yǒu diǎn luò hòu 。', 'Kết quả học tập của lớp chúng tôi hơi bị tụt hậu về môn toán.', 'monchinese', 1303) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
