INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '專利', 'zhuānlì', 'bằng sáng chế', 'N', '他申請了一項新專利。', 'tā shēn qǐng le yí xiàng xīn zhuān lì 。', 'Anh ấy đã nộp đơn xin một bằng sáng chế mới.', 'monchinese', 1360) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '專門', 'zhuānmén', 'chuyên môn, chuyên', 'Vs', '這本書是專門寫給小孩看的。', 'zhè běn shū shì zhuān mén xiě gěi xiǎo hái kàn de 。', 'Cuốn sách này chuyên viết cho trẻ em đọc.', 'monchinese', 1361) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '專人', 'zhuānrén', 'người chuyên trách', 'N', '這件事會由專人處理。', 'zhè jiàn shì huì yóu zhuān rén chǔ lǐ 。', 'Việc này sẽ do người chuyên trách xử lý.', 'monchinese', 1362) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
