INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '專業', 'zhuānyè', 'chuyên ngành, chuyên nghiệp', 'N', '他是一位很專業的醫師。', 'tā shì yí wèi hěn zhuān yè de yī shī 。', 'Anh ấy là một bác sĩ rất chuyên nghiệp.', 'monchinese', 1364) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '茶會', 'cháhuì', 'tiệc trà', 'N', '我們週末要去參加一個茶會。', 'wǒ men zhōu mò yào qù cān jiā yí gè chá huì 。', 'Cuối tuần này chúng tôi sẽ đi dự một buổi tiệc trà.', 'monchinese', 1365) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
