INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '回教', 'Huíjiào', 'Hồi giáo', 'N', '台灣有一些回教徒，他們有自己的清真寺。', 'tái wān yǒu yì xiē huí jiào tú ， tā men yǒu zì jǐ de qīng zhēn sì 。', 'Đài Loan có một số người theo đạo Hồi, họ có nhà thờ Hồi giáo riêng.', 'monchinese', 1367) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '匯款', 'huìkuǎn', 'chuyển tiền, gửi tiền', 'V-sep', '我今天要去郵局匯款給媽媽。', 'wǒ jīn tiān yào qù yóu jú huì kuǎn gěi mā mā 。', 'Hôm nay tôi sẽ ra bưu điện chuyển tiền cho mẹ.', 'monchinese', 1368) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '灰色', 'huīsè', 'màu xám', 'N', '我喜歡穿灰色的衣服，看起來很舒服。', 'wǒ xǐ huān chuān huī sè de yī fu ， kàn qǐ lái hěn shū fú 。', 'Tôi thích mặc quần áo màu xám, trông rất thoải mái.', 'monchinese', 1369) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
