INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '會員', 'huìyuán', 'hội viên', 'N', '我是這家咖啡店的會員，每次消費都有折扣。', 'wǒ shì zhè jiā kā fēi diàn de huì yuán ， měi cì xiāo fèi dōu yǒu zhé kòu 。', 'Tôi là hội viên của quán cà phê này, mỗi lần tiêu dùng đều được giảm giá.', 'monchinese', 1372) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
