INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '昏迷', 'hūnmí', 'hôn mê', 'Vp', '他因為車禍受傷嚴重，目前還在昏迷中。', 'tā yīn wéi chē huò shòu shāng yán zhòng ， mù qián hái zài hūn mí zhōng 。', 'Anh ấy vì tai nạn xe cộ bị thương nặng, hiện tại vẫn còn đang hôn mê.', 'monchinese', 1388) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '求婚', 'qiúhūn', 'cầu hôn', 'V-sep', '他單膝跪地向她求婚。', 'tā dān xī guì dì xiàng tā qiú hūn 。', 'Anh ta quỳ một gối xuống cầu hôn cô ấy.', 'monchinese', 1389) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
