INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '準確', 'zhǔnquè', 'chính xác, đúng', 'Vs', '他說的話很準確，跟事實完全相符。', 'tā shuō de huà hěn zhǔn què ， gēn shì shí wán quán xiāng fú 。', 'Lời anh ấy nói rất chính xác, hoàn toàn khớp với sự thật.', 'monchinese', 1395) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '準考證', 'zhǔnkǎozhèng', 'thẻ dự thi', 'N', '考試前記得帶準考證。', 'kǎo shì qián jì dé dài zhǔn kǎo zhèng 。', 'Trước khi thi nhớ mang theo thẻ dự thi.', 'monchinese', 1396) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '獲得', 'huòdé', 'đạt được, giành được', 'Vpt', '他努力學習，終於獲得了好成績。', 'tā nǔ lì xué xí ， zhōng wū huò dé le hǎo chéng jì 。', 'Anh ấy đã cố gắng học tập, cuối cùng đã đạt được thành tích tốt.', 'monchinese', 1397) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '活力', 'huólì', 'sức sống, sinh khí', 'N', '這位年輕人充滿了活力。', 'zhè wèi nián qīng rén chōng mǎn le huó lì 。', 'Người thanh niên này tràn đầy sức sống.', 'monchinese', 1398) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
