INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '老實說', 'lǎoshíshuō', 'thành thật mà nói', 'Conj', '老實說，我不太喜歡那部電影。', 'lǎo shí shuō ， wǒ bú tài xǐ huān nà bù diàn yǐng 。', 'Thành thật mà nói, tôi không thích bộ phim đó lắm.', 'monchinese', 1411) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
