INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '平靜', 'píngjìng', 'bình tĩnh, yên tĩnh', 'Vs', '湖水很平靜。', 'hú shuǐ hěn píng jìng 。', 'Mặt hồ rất yên tĩnh.', 'monchinese', 1505) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '前進', 'qiánjìn', 'tiến lên, đi về phía trước', 'V', '我們要勇敢地前進。', 'wǒ men yào yǒng gǎn dì qián jìn 。', 'Chúng ta phải dũng cảm tiến lên.', 'monchinese', 1506) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '如今', 'rújīn', 'ngày nay, hiện nay', 'N', '如今，科技發展非常快速。', 'rú jīn ， kē jì fā zhǎn fēi cháng kuài sù 。', 'Ngày nay, công nghệ phát triển rất nhanh.', 'monchinese', 1507) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神經', 'shénjīng', 'thần kinh', 'N', '長時間使用手機可能會傷害到手部神經。', 'cháng shí jiàn shǐ yòng shǒu jī kě néng huì shāng hài dào shǒu bù shén jīng 。', 'Sử dụng điện thoại di động trong thời gian dài có thể làm tổn thương dây thần kinh ở tay.', 'monchinese', 1508) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '現金', 'xiànjīn', 'tiền mặt', 'N', '我只有現金。', 'wǒ zhǐ yǒu xiàn jīn 。', 'Tôi chỉ có tiền mặt.', 'monchinese', 1509) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '先進', 'xiānjìn', 'tiên tiến', 'Vs', '我們的科技很先進。', 'wǒ men de kē jì hěn xiān jìn 。', 'Công nghệ của chúng tôi rất tiên tiến.', 'monchinese', 1510) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '鏡(子)', 'jìng(zi)', 'cái gương', 'N', '我每天出門前都會照鏡子。', 'wǒ měi tiān chū mén qián dōu huì zhào jìng zǐ 。', 'Tôi soi gương mỗi ngày trước khi ra ngoài.', 'monchinese', 1511) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '就是', 'jiùshì', 'chính là, chỉ là', 'Adv', '就是這杯珍珠奶茶，我今天就是想喝這個。', 'jiù shì zhè bēi zhēn zhū nǎi chá ， wǒ jīn tiān jiù shì xiǎng hē zhè gè 。', 'Chính là ly trà sữa trân châu này, hôm nay tôi chỉ muốn uống cái này thôi.', 'monchinese', 1512) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '就業', 'jiùyè', 'có việc làm, tìm việc làm', 'Vi', '大學畢業後，他很快就找到就業機會。', 'dà xué bì yè hòu ， tā hěn kuài jiù zhǎo dào jiù yè jī huì 。', 'Sau khi tốt nghiệp đại học, anh ấy nhanh chóng tìm được cơ hội việc làm.', 'monchinese', 1513) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
