INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神奇', 'shénqí', 'thần kỳ, kỳ diệu', 'Vs', '臺灣的夜市有許多神奇的小吃，每次都能發現新口味。', 'tái wān de yè shì yǒu xū duō shén qí de xiǎo chī ， měi cì dōu néng fā xiàn xīn kǒu wèi 。', 'Chợ đêm Đài Loan có nhiều món ăn vặt thần kỳ, mỗi lần đều có thể khám phá hương vị mới.', 'monchinese', 1680) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
