INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '論文', 'lùnwén', 'luận văn', 'N', '我暑假要寫一篇關於臺灣小吃的論文。', 'wǒ shǔ jià yào xiě yì piān guān wū tái wān xiǎo chī de lùn wén 。', 'Kỳ nghỉ hè này tôi phải viết một luận văn về các món ăn vặt Đài Loan.', 'monchinese', 1683) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
