INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '面談', 'miàntán', 'phỏng vấn trực tiếp, gặp mặt nói chuyện', 'Vi', '經過電話聯繫，我們約好明天面談。', 'jīng guò diàn huà lián xì ， wǒ men yuē hǎo míng tiān miàn tán 。', 'Sau khi liên lạc qua điện thoại, chúng tôi đã hẹn ngày mai gặp mặt nói chuyện.', 'monchinese', 1730) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '面子', 'miànzi', 'thể diện, sĩ diện', 'N', '他很愛面子，所以不喜歡在公開場合被批評。', 'tā hěn ài miàn zi ， suǒ yǐ bù xǐ huān zài gōng kāi chǎng hé bèi pī píng 。', 'Anh ấy rất trọng thể diện, nên không thích bị chỉ trích ở nơi công cộng.', 'monchinese', 1731) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '片面', 'piànmiàn', 'phiến diện, một chiều', 'Vs-attr', '這份報導內容很片面。', 'zhè fèn bào dǎo nèi róng hěn piàn miàn 。', 'Nội dung bản báo cáo này rất phiến diện.', 'monchinese', 1732) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
