INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '失眠', 'shīmián', 'mất ngủ', 'Vp', '考試前一晚，許多學生會因為壓力大而失眠。', 'kǎo shì qián yì wǎn ， xū duō xué shēng huì yīn wéi yā lì dà ér shī mián 。', 'Đêm trước kỳ thi, nhiều học sinh sẽ bị mất ngủ vì áp lực lớn.', 'monchinese', 1734) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
