INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '師母', 'shīmǔ', 'sư mẫu, vợ của thầy', 'N', '以前在眷村裡，大家都對師母非常尊敬，把她當作長輩。', 'yǐ qián zài juàn cūn lǐ ， dà jiā dōu duì shī mǔ fēi cháng zūn jìng ， bǎ tā dāng zuò cháng bèi 。', 'Ngày xưa ở làng quân nhân, mọi người đều rất kính trọng sư mẫu, coi bà như bậc trưởng bối.', 'monchinese', 1773) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
