INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '新娘', 'xīnniáng', 'cô dâu', 'N', '新娘今天穿了一件很漂亮的婚紗。', 'xīn niáng jīn tiān chuān le yí jiàn hěn piào liang de hūn shā 。', 'Cô dâu hôm nay mặc một chiếc váy cưới rất đẹp.', 'monchinese', 1799) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
