INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '寧可', 'níngkě', 'thà, thà rằng', 'Vaux', '我寧可在家看書，也不想出去。', 'wǒ níng kě zài jiā kàn shū ， yě bù xiǎng chū qù 。', 'Tôi thà ở nhà đọc sách còn hơn là đi ra ngoài.', 'monchinese', 1802) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '寧願', 'níngyuàn', 'thà, tình nguyện', 'Vaux', '我寧願走路上學，也不想搭公車。', 'wǒ níng yuàn zǒu lù shang xué ， yě bù xiǎng dā gōng chē 。', 'Tôi thà đi bộ đến trường còn hơn là đi xe buýt.', 'monchinese', 1803) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '賽跑', 'sàipǎo', 'chạy đua, thi chạy', 'Vi', '我們班明天要舉行賽跑。', 'wǒ men bān míng tiān yào jǔ xíng sài pǎo 。', 'Lớp chúng ta ngày mai sẽ tổ chức chạy đua.', 'monchinese', 1804) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
