INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '食品', 'shípǐn', 'thực phẩm', 'N', '臺灣的便利商店販售各式各樣的食品，從便當到零食應有盡有。', 'tái wān de biàn lì shāng diàn fàn shòu gè shì gè yàng de shí pǐn ， cóng biàn dāng dào líng shí yīng yǒu jìn yǒu 。', 'Các cửa hàng tiện lợi ở Đài Loan bán đủ loại thực phẩm, từ cơm hộp đến đồ ăn vặt.', 'monchinese', 1851) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '文憑', 'wénpíng', 'văn bằng, bằng cấp', 'N', '畢業後，我拿到了一張大學文憑。', 'bì yè hòu ， wǒ ná dào le yì zhāng dà xué wén píng 。', 'Sau khi tốt nghiệp, tôi đã nhận được một tấm bằng đại học.', 'monchinese', 1852) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '樣品', 'yàngpǐn', 'hàng mẫu, vật mẫu', 'N', '這是一個產品樣品。', 'zhè shì yí gè chǎn pǐn yàng pǐn 。', 'Đây là một mẫu sản phẩm.', 'monchinese', 1853) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '贈品', 'zèngpǐn', 'quà tặng kèm, hàng khuyến mãi', 'N', '買咖啡送贈品。', 'mǎi kā fēi sòng zèng pǐn 。', 'Mua cà phê tặng quà.', 'monchinese', 1854) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '詩', 'shī', 'thơ, thi', 'N', '小學的時候，老師常教我們朗讀臺灣本土詩人的詩。', 'xiǎo xué de shí hòu ， lǎo shī cháng jiào wǒ men lǎng dú tái wān běn tǔ shī rén de shī 。', 'Khi học tiểu học, thầy cô thường dạy chúng tôi đọc thơ của các nhà thơ bản địa Đài Loan.', 'monchinese', 1855) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '愛人', 'àirén', 'người yêu, vợ hoặc chồng', 'N', '他很愛他的愛人。', 'tā hěn ài tā de ài rén 。', 'Anh ấy rất yêu người yêu của mình.', 'monchinese', 1856) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '按', 'àn', 'ấn, bấm', 'V', '請按順序排隊。', 'qǐng àn shùn xù pái duì 。', 'Xin hãy xếp hàng theo thứ tự.', 'monchinese', 1857) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
