INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '發行', 'fāxíng', 'phát hành', 'V', '這本書今年發行。', 'zhè běn shū jīn nián fā xíng 。', 'Cuốn sách này được phát hành năm nay.', 'monchinese', 1859) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '計算', 'jìsuàn', 'tính toán', 'V', '老師教我們如何計算圓周長。', 'lǎo shī jiào wǒ men rú hé jì suàn yuán zhōu cháng 。', 'Cô giáo dạy chúng tôi cách tính chu vi hình tròn.', 'monchinese', 1860) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '記載', 'jìzài', 'ghi chép lại, biên niên', 'V', '這本書記載了許多歷史事件。', 'zhè běn shū jì zài le xū duō lì shǐ shì jiàn 。', 'Cuốn sách này ghi chép lại nhiều sự kiện lịch sử.', 'monchinese', 1861) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
