INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '普及', 'pǔjí', 'phổ cập, phổ biến', 'Vs', '智慧型手機現在很普及。', 'zhì huì xíng shǒu jī xiàn zài hěn pǔ jí 。', 'Điện thoại thông minh hiện nay rất phổ biến.', 'monchinese', 1863) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
