INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '衣裳', 'yīshang', 'quần áo, y phục (văn nói)', 'N', '她今天穿了一件漂亮的衣裳。', 'tā jīn tiān chuān le yí jiàn piào liang de yī shang 。', 'Hôm nay cô ấy mặc một bộ y phục đẹp.', 'monchinese', 1969) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '事實上', 'shìshíshàng', 'trên thực tế, thực ra', 'Adv', '大家以為臭豆腐聞起來很臭，但事實上吃起來非常香。', 'dà jiā yǐ wéi chòu dòu fu wén qǐ lái hěn chòu ， dàn shì shí shàng chī qǐ lái fēi cháng xiāng 。', 'Mọi người đều nghĩ đậu phụ thối có mùi rất hôi, nhưng thực ra ăn rất thơm ngon.', 'monchinese', 1970) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '發射', 'fāshè', 'phóng, bắn', 'V', '火箭準備發射了。', 'huǒ jiàn zhǔn bèi fā shè le 。', 'Tên lửa chuẩn bị phóng.', 'monchinese', 1971) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '設立', 'shèlì', 'thành lập, thiết lập', 'V', '這家連鎖飲料店決定在臺中設立新的分店。', 'zhè jiā lián suǒ yǐn liào diàn jué dìng zài tái zhōng shè lì xīn de fēn diàn 。', 'Chuỗi cửa hàng đồ uống này quyết định thành lập một chi nhánh mới tại Đài Trung.', 'monchinese', 1972) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神秘', 'shénmì', 'thần bí, bí ẩn', 'Vs', '這個地方有一種神秘的氣氛，讓人很好奇。', 'zhè gè dì fāng yǒu yì zhǒng shén mì de qì fēn ， ràng rén hěn hào qí 。', 'Nơi này có một bầu không khí huyền bí, khiến người ta rất tò mò.', 'monchinese', 1973) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '神仙', 'shénxiān', 'thần tiên', 'N', '臺灣傳統故事裡，常常會提到八仙過海的神仙。', 'tái wān chuán tǒng gù shì lǐ ， cháng cháng huì tí dào bā xiān guò hǎi de shén xiān 。', 'Trong các câu chuyện truyền thống Đài Loan, thường nhắc đến các vị thần tiên Bát Tiên quá hải.', 'monchinese', 1974) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '深夜', 'shēnyè', 'đêm khuya', 'N', '臺灣的便利商店即使深夜也燈火通明，非常方便。', 'tái wān de biàn lì shāng diàn jí shǐ shēn yè yě dēng huǒ tōng míng ， fēi cháng fāng biàn 。', 'Các cửa hàng tiện lợi ở Đài Loan dù là đêm khuya cũng sáng đèn, rất tiện lợi.', 'monchinese', 1975) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '舌頭', 'shétou', 'cái lưỡi', 'N', '吃麻辣鍋的時候，湯頭太辣會讓舌頭麻痺。', 'chī má là guō de shí hòu ， tāng tóu tài là huì ràng shé tóu má bì 。', 'Khi ăn lẩu cay, nếu nước lẩu quá cay sẽ làm tê lưỡi.', 'monchinese', 1976) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '社團', 'shètuán', 'câu lạc bộ, đoàn thể', 'N', '大學生活很精彩，可以多參加一些像熱音社、吉他社的社團。', 'dà xué shēng huó hěn jīng cǎi ， kě yǐ duō cān jiā yì xiē xiàng rè yīn shè 、 jí tā shè de shè tuán 。', 'Cuộc sống đại học rất thú vị, bạn có thể tham gia nhiều câu lạc bộ như câu lạc bộ nhạc rock, câu lạc bộ ghi-ta.', 'monchinese', 1977) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '攝影', 'shèyǐng', 'nhiếp ảnh, quay phim', 'Vi', '很多人到臺灣旅遊，喜歡用手機攝影記錄下美景和美食。', 'hěn duō rén dào tái wān lǚ yóu ， xǐ huān yòng shǒu jī shè yǐng jì lù xià měi jǐng hé měi shí 。', 'Nhiều người đến Đài Loan du lịch, thích dùng điện thoại để chụp ảnh ghi lại cảnh đẹp và món ngon.', 'monchinese', 1978) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '設置', 'shèzhì', 'thiết lập, cài đặt', 'V', '為了方便民眾，臺北市政府在公園裡設置了許多運動器材。', 'wéi le fāng biàn mín zhòng ， tái běi shì zhèng fǔ zài gōng yuán lǐ shè zhì le xū duō yùn dòng qì cái 。', 'Để thuận tiện cho người dân, Chính quyền thành phố Đài Bắc đã lắp đặt nhiều thiết bị tập thể dục trong công viên.', 'monchinese', 1979) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '注射', 'zhùshè', 'tiêm, chích', 'V', '醫生幫我注射了一劑疫苗。', 'yī shēng bāng wǒ zhù shè le yí jì yì miáo 。', 'Bác sĩ đã tiêm cho tôi một liều vắc-xin.', 'monchinese', 1980) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '維生素', 'wéishēngsù', 'vitamin', 'N', '多吃水果補充維生素。', 'duō chī shuǐ guǒ bǔ chōng wéi shēng sù 。', 'Ăn nhiều trái cây để bổ sung vitamin.', 'monchinese', 1981) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '繩(子)', 'shéng(zi)', 'sợi dây, dây thừng', 'N', '小朋友在公園裡玩跳繩，消耗體力。', 'xiǎo péng yǒu zài gōng yuán lǐ wán tiào shéng ， xiāo hào tǐ lì 。', 'Các em nhỏ chơi nhảy dây trong công viên, tiêu hao năng lượng.', 'monchinese', 1982) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '手術', 'shǒushù', 'phẫu thuật, ca mổ', 'N', '他明天要動手術。', 'tā míng tiān yào dòng shǒu shù 。', 'Anh ấy ngày mai phải phẫu thuật.', 'monchinese', 1983) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '首先', 'shǒuxiān', 'đầu tiên, trước hết', 'Adv', '首先，請大家安靜。', 'shǒu xiān ， qǐng dà jiā ān jìng 。', 'Trước hết, xin mọi người hãy giữ trật tự.', 'monchinese', 1984) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '享受', 'xiǎngshòu', 'hưởng thụ, tận hưởng', 'Vst', '我很享受假期。', 'wǒ hěn xiǎng shòu jià qī 。', 'Tôi rất tận hưởng kỳ nghỉ.', 'monchinese', 1985) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '銷售', 'xiāoshòu', 'bán, tiêu thụ', 'V', '這家店銷售很多台灣特色禮品。', 'zhè jiā diàn xiāo shòu hěn duō tái wān tè sè lǐ pǐn 。', 'Cửa hàng này bán rất nhiều quà lưu niệm đặc trưng của Đài Loan.', 'monchinese', 1986) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '選手', 'xuǎnshǒu', 'tuyển thủ, vận động viên', 'N', '這位選手跑得很快。', 'zhè wèi xuǎn shǒu pǎo dé hěn kuài 。', 'Vận động viên này chạy rất nhanh.', 'monchinese', 1987) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
