INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '遭受', 'zāoshòu', 'chịu đựng, bị', 'Vst', '他遭受了很大的壓力。', 'tā zāo shòu le hěn dà de yā lì 。', 'Anh ấy chịu đựng áp lực rất lớn.', 'monchinese', 1989) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '遵守', 'zūnshǒu', 'tuân thủ', 'Vst', '我們必須遵守交通規則。', 'wǒ men bì xū zūn shǒu jiāo tōng guī zé 。', 'Chúng ta phải tuân thủ luật giao thông.', 'monchinese', 1990) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '秘書', 'mìshū', 'thư ký', 'N', '老闆的秘書每天都很忙，要處理很多文件。', 'lǎo bǎn de mì shū měi tiān dōu hěn máng ， yào chǔ lǐ hěn duō wén jiàn 。', 'Thư ký của ông chủ công ty mỗi ngày đều rất bận, phải xử lý nhiều tài liệu.', 'monchinese', 1991) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
