INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '課外', 'kèwài', 'ngoại khóa', 'Vs-attr', '我常參加課外活動。', 'wǒ cháng cān jiā kè wài huó dòng 。', 'Tôi thường tham gia các hoạt động ngoại khóa.', 'monchinese', 2054) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
