INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '失望', 'shīwàng', 'thất vọng', 'Vs', '颱風天原本計畫去墾丁玩，結果行程取消讓我有點失望。', 'tái fēng tiān yuán běn jì huà qù kěn dīng wán ， jié guǒ xíng chéng qǔ xiāo ràng wǒ yǒu diǎn shī wàng 。', 'Ngày bão, ban đầu tôi định đi chơi Kenting, nhưng kết quả là lịch trình bị hủy khiến tôi hơi thất vọng.', 'monchinese', 2061) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
