INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '因而', 'yīn&#x27;ér', 'do đó, vì vậy', 'Conj', '他很用功，因而成績很好。', 'tā hěn yòng gōng ， yīn ér chéng jì hěn hǎo 。', 'Anh ấy rất chăm chỉ, do đó thành tích học tập rất tốt.', 'monchinese', 2174) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
