INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '應付', 'yìngfù', 'đối phó, ứng phó', 'V', '他每天都要應付很多工作。', 'tā měi tiān dōu yào yīng fù hěn duō gōng zuò 。', 'Anh ấy phải đối phó với rất nhiều công việc mỗi ngày.', 'monchinese', 2176) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '應用', 'yìngyòng', 'ứng dụng, áp dụng', 'V', '我們應該把學到的知識應用到生活中。', 'wǒ men yīng gāi bǎ xué dào de zhī shí yīng yòng dào shēng huó zhōng 。', 'Chúng ta nên áp dụng kiến thức đã học vào cuộc sống.', 'monchinese', 2177) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
