INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '志氣', 'zhìqì', 'chí khí', 'N', '他很有志氣，想當個醫生。', 'tā hěn yǒu zhì qì ， xiǎng dāng gè yī shēng 。', 'Anh ấy rất có chí khí, muốn trở thành bác sĩ.', 'monchinese', 2230) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '指示', 'zhǐshì', 'chỉ thị, sự chỉ dẫn', 'N / V', '醫生指示病人要多休息。', 'yī shēng zhǐ shì bìng rén yào duō xiū xi 。', 'Bác sĩ chỉ thị bệnh nhân phải nghỉ ngơi nhiều.', 'monchinese', 2231) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '制止', 'zhìzhǐ', 'ngăn chặn, đình chỉ', 'V', '老師制止學生吵鬧。', 'lǎo shī zhì zhǐ xué shēng chǎo nào 。', 'Thầy giáo ngăn chặn học sinh ồn ào.', 'monchinese', 2232) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '阻止', 'zǔzhǐ', 'ngăn cản, ngăn chặn', 'V', '我們應該阻止他做錯事。', 'wǒ men yīng gāi zǔ zhǐ tā zuò cuò shì 。', 'Chúng ta nên ngăn cản anh ấy làm điều sai trái.', 'monchinese', 2233) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '互助', 'hùzhù', 'tương trợ, giúp đỡ lẫn nhau', 'Vi', '我們應該互助合作，把事情做好。', 'wǒ men yīng gāi hù zhù hé zuò ， bǎ shì qíng zuò hǎo 。', 'Chúng ta nên tương trợ hợp tác, làm tốt mọi việc.', 'monchinese', 2234) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '註冊', 'zhùcè', 'đăng ký', 'V-sep', '註冊這個網站很簡單，只要填寫基本資料就好。', 'zhù cè zhè gè wǎng zhàn hěn jiǎn dān ， zhǐ yào tián xiě jī běn zī liào jiù hǎo 。', 'Đăng ký trang web này rất đơn giản, chỉ cần điền thông tin cơ bản.', 'monchinese', 2235) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.full_dictionary_words (level, hanzi, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', '主持', 'zhǔchí', 'chủ trì, dẫn chương trình', 'V', '她很會主持班級活動，讓氣氛很熱絡。', 'tā hěn huì zhǔ chí bān jí huó dòng ， ràng qì fēn hěn rè luò 。', 'Cô ấy rất giỏi trong việc chủ trì các hoạt động của lớp, làm cho không khí trở nên sôi nổi.', 'monchinese', 2236) ON CONFLICT (level, hanzi, pinyin) DO UPDATE SET vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
